CREATE PROCEDURE IssueBook(
  @BookID INT,
  @MemberID INT,
  @LoanDate DATE
)
AS
BEGIN
  SET NOCOUNT ON;
  DECLARE @Available INT;
  SELECT @Available = AvailableCopies FROM Book WHERE BookID = @BookID;
  IF @Available > 0
  BEGIN
    UPDATE Book SET AvailableCopies = AvailableCopies - 1 WHERE BookID = @BookID;
    INSERT INTO Loan (BookID, MemberID, LoanDate, DueDate)
    VALUES (@BookID, @MemberID, @LoanDate, DATEADD(DAY, 14, @LoanDate));
    SELECT 'Book issued successfully' AS Message;
  END
  ELSE
    SELECT 'No copies available' AS Error;
END;
