CREATE PROCEDURE sp_IssueBook
    @BookID INT,
    @MemberID INT,
    @LoanDate DATE
AS
BEGIN
    BEGIN TRANSACTION;
    DECLARE @AvailableCopies INT;
    SELECT @AvailableCopies = AvailableCopies FROM Books WHERE BookID = @BookID;
    IF @AvailableCopies IS NULL OR @AvailableCopies <= 0
    BEGIN
        ROLLBACK;
        RAISERROR('Book unavailable', 16, 1);
        RETURN;
    END
    UPDATE Books SET AvailableCopies = AvailableCopies - 1 WHERE BookID = @BookID;
    INSERT INTO Loan (BookID, MemberID, LoanDate, DueDate, ReturnDate)
    VALUES (@BookID, @MemberID, @LoanDate, DATEADD(day, 14, @LoanDate), NULL);
    COMMIT;
    SELECT 'Book issued successfully' AS Status;
END;
