CREATE PROCEDURE IssueBook
    @p_BookID INT,
    @p_MemberID INT,
    @p_LoanDate DATE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @available INT, @existingLoan INT;
    -- Check if member already has the book not returned
    SELECT @existingLoan = COUNT(*) FROM Loan WHERE BookID = @p_BookID AND MemberID = @p_MemberID AND ReturnDate IS NULL;
    IF @existingLoan > 0
    BEGIN
        RAISERROR('Member has already borrowed this book and not returned', 16, 1);
        RETURN;
    END
    -- Get available copies
    SELECT @available = AvailableCopies FROM Book WHERE BookID = @p_BookID;
    IF @available IS NULL
    BEGIN
        RAISERROR('Invalid Book ID', 16, 1);
        RETURN;
    END
    IF @available <= 0
    BEGIN
        RAISERROR('No copies available', 16, 1);
        RETURN;
    END
    BEGIN TRANSACTION;
    UPDATE Book SET AvailableCopies = AvailableCopies - 1 WHERE BookID = @p_BookID;
    INSERT INTO Loan (BookID, MemberID, LoanDate, DueDate)
    VALUES (@p_BookID, @p_MemberID, @p_LoanDate, DATEADD(DAY, 14, @p_LoanDate));
    COMMIT TRANSACTION;
    SELECT 'Book issued successfully' AS Message, @@IDENTITY AS LoanID;
END;
